import { slugify } from "@/lib/news-data";

export type Row = {
  id: number;
  title: string;
  slug: string;
  category: string;
  city: string;
  state: string;
  country: string;
  author: string;
  views: number;
  status: "Published" | "Draft" | "Review";
  date: string;
  excerpt: string;
  content: string;
  featuredImage: string;
  ogImage: string;
  imageCaption?: string;
  imageCredit?: string;
  metaTitle: string;
  metaDescription: string;
  tags: string;
  featured: boolean;
  newsType: "Standard" | "Breaking" | "Featured" | "Exclusive" | "Opinion" | "Video";
  journalistId: string;
  journalistName: string;
  access_level: "Free" | "Premium";
};

export const statusStyle: Record<Row["status"], string> = {
  Published: "bg-emerald-50 text-emerald-700 border-emerald-200",
  Draft: "bg-slate-100 text-slate-700 border-slate-200",
  Review: "bg-amber-50 text-amber-700 border-amber-200",
};

export type Tab = "content" | "media" | "seo" | "settings";

export const getDomain = () => {
  if (typeof window !== "undefined") {
    return window.location.host;
  }
  return "northeasttimeline.com";
};

export const fullUrl = (r: Row) => {
  const domain = getDomain();
  const title = r.slug || slugify(r.title) || "news-title";
  return [domain, "news", title].filter(Boolean).join("/");
};

export const formatDateTimeLocal = (dateVal: any): string => {
  if (!dateVal) return "";
  try {
    if (typeof dateVal === "string") {
      const s = dateVal.trim();
      // If already YYYY-MM-DDTHH:mm, return first 16 chars
      if (s.includes("T")) {
        const d = new Date(s);
        if (!isNaN(d.getTime())) {
          const pad = (n: number) => String(n).padStart(2, "0");
          return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
        }
        return s.slice(0, 16);
      }
      // If MySQL 'YYYY-MM-DD HH:mm:ss' format
      if (s.includes(" ")) {
        const iso = s.replace(" ", "T");
        const d = new Date(iso);
        if (!isNaN(d.getTime())) {
          const pad = (n: number) => String(n).padStart(2, "0");
          return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
        }
        return iso.slice(0, 16);
      }
      return s.slice(0, 16);
    }
    if (dateVal instanceof Date && !isNaN(dateVal.getTime())) {
      const pad = (n: number) => String(n).padStart(2, "0");
      return `${dateVal.getFullYear()}-${pad(dateVal.getMonth() + 1)}-${pad(dateVal.getDate())}T${pad(dateVal.getHours())}:${pad(dateVal.getMinutes())}`;
    }
  } catch (e) {
    console.error("formatDateTimeLocal error:", e);
  }
  return "";
};

export type ArticleStatus = Row["status"];

